#include "dx_iface.h"
#include "libdwgr.h"
#include <memory>
#include <iostream>
class Producer : public dx_iface {
public:
 explicit Producer(dwgRW& writer) : w(writer) { cData=&data; currentBlock=data.mBlock; }
 void writeHeader(DRW_Header& h) override { h.vars.clear(); }
 void writeBlocks() override {} void writeBlockRecords() override {}
 void writeLTypes() override {} void writeLayers() override {}
 void writeTextstyles() override {} void writeVports() override {}
 void writeDimstyles() override {} void writeAppId() override {}
 void writeEntities() override {
  DRW_MPolygon polygon; polygon.name="SOLID"; polygon.solid=1; polygon.fillColorAci=3; polygon.xDirX=2; polygon.xDirY=5;
  auto loop=std::make_shared<DRW_HatchLoop>(2);
  auto poly=std::make_shared<DRW_LWPolyline>(); poly->flags=1;
  poly->addVertex(DRW_Vertex2D(1,2,0)); poly->addVertex(DRW_Vertex2D(4,2,0)); poly->addVertex(DRW_Vertex2D(3,5,0));
  loop->objlist.push_back(poly); loop->update(); polygon.appendLoop(loop);
  wrote=w.writeMPolygon(&polygon);
 }
 bool wrote=false;
private: dwgRW& w; dx_data data;
};
int main(int argc,char** argv) { if(argc!=2) return 2; dwgRW w(argv[1]); Producer p(w); bool ok=w.write(&p,DRW::AC1018,true); std::cout << "writer=" << ok << " polygon=" << p.wrote << '\n'; return ok&&p.wrote?0:1; }

