#include <cad/primitive/lwpolyline.h>
TEST(DwgImportBoundaryProbe, GeneratedClosedMPolygon) {
    auto doc = newDwgDocument();
    const auto read = lc::persistence::File::importFile(doc,
        "/private/tmp/librecad-installed-cli-20261115/mpolygon-closed.dwg",
        lc::persistence::File::LIBDXFRW);
    ASSERT_TRUE(read.ok);
    ASSERT_FALSE(read.partial);
    EXPECT_TRUE(read.loss.empty()); // Existing behavior: subtype projection is not reported.
    lc::entity::Hatch_CSPtr hatch;
    for (const auto& e : doc->entityContainer().asVector())
        if (auto h = std::dynamic_pointer_cast<const lc::entity::Hatch>(e)) hatch = h;
    ASSERT_NE(hatch, nullptr);
    ASSERT_EQ(hatch->getRegion().loopList().size(), 1u);
    const auto& entities=hatch->getRegion().loopList()[0].entities();
    ASSERT_EQ(entities.size(), 1u);
    const auto poly=std::dynamic_pointer_cast<const lc::entity::LWPolyline>(entities[0]);
    ASSERT_NE(poly,nullptr);
    ASSERT_TRUE(poly->closed());
    ASSERT_EQ(poly->vertex().size(),3u);
    EXPECT_DOUBLE_EQ(poly->vertex()[0].location().x(),1.0);
    EXPECT_DOUBLE_EQ(poly->vertex()[0].location().y(),2.0);
    EXPECT_DOUBLE_EQ(poly->vertex()[1].location().x(),4.0);
    EXPECT_DOUBLE_EQ(poly->vertex()[1].location().y(),2.0);
    EXPECT_DOUBLE_EQ(poly->vertex()[2].location().x(),3.0);
    EXPECT_DOUBLE_EQ(poly->vertex()[2].location().y(),5.0);
    const std::string out="/private/tmp/librecad-installed-cli-20261115/mpolygon-closed-export.dxf";
    const auto written=lc::persistence::File::exportFile(doc,out,lc::persistence::File::LIBDXFRW_DXF_R2000);
    EXPECT_TRUE(written.ok);
    EXPECT_EQ(written.loss.total(),0u);
    auto reopened=newDwgDocument();
    ASSERT_TRUE(lc::persistence::File::importFile(reopened,out,lc::persistence::File::LIBDXFRW).ok);
    lc::entity::Hatch_CSPtr copied;
    for (const auto& e : reopened->entityContainer().asVector())
        if(auto h=std::dynamic_pointer_cast<const lc::entity::Hatch>(e)) copied=h;
    ASSERT_NE(copied,nullptr);
    ASSERT_EQ(copied->getRegion().loopList().size(),1u);
    const auto& copiedEntities=copied->getRegion().loopList()[0].entities();
    ASSERT_EQ(copiedEntities.size(),1u);
    const auto copiedPoly=std::dynamic_pointer_cast<const lc::entity::LWPolyline>(copiedEntities[0]);
    ASSERT_NE(copiedPoly,nullptr);
    ASSERT_TRUE(copiedPoly->closed());
    ASSERT_EQ(copiedPoly->vertex().size(),3u);
    EXPECT_DOUBLE_EQ(copiedPoly->vertex()[0].location().x(),1.0);
    EXPECT_DOUBLE_EQ(copiedPoly->vertex()[0].location().y(),2.0);
    EXPECT_DOUBLE_EQ(copiedPoly->vertex()[1].location().x(),4.0);
    EXPECT_DOUBLE_EQ(copiedPoly->vertex()[1].location().y(),2.0);
    EXPECT_DOUBLE_EQ(copiedPoly->vertex()[2].location().x(),3.0);
    EXPECT_DOUBLE_EQ(copiedPoly->vertex()[2].location().y(),5.0);
    // Retain scratch output for independent inspection.
}
